const VAULT_STORAGE = 'lumora.encrypted-vault.v1';
const RECOVERY_STORAGE = 'lumora.recovery-key.v1';
const PREFS_STORAGE = 'lumora.preferences.v1';
const encoder = new TextEncoder();
const decoder = new TextDecoder();

type LoginRecord = { id: string; name: string; username: string; password: string; url: string; category: string; favorite: boolean; deleted: boolean; updatedAt: string; createdAt: string };
type ActivityEvent = { id: string; action: string; recordName: string; timestamp: string };
type ActiveView = 'all' | 'favorites' | 'trash' | 'activity' | 'settings';
type Theme = 'light' | 'dark';
type VaultPayload = { records: LoginRecord[]; activity: ActivityEvent[] };
type Preferences = { theme: Theme; activeView: ActiveView };

