function Login() {
  const { unlock, unlocked, recoveryKey, resetWithRecovery, theme } = useVault(); const [, setLocation] = useLocation(); const [mode, setMode] = useState<'unlock' | 'create' | 'recover'>('unlock'); const [passphrase, setPassphrase] = useState(''); const [confirm, setConfirm] = useState(''); const [recovery, setRecovery] = useState(''); const [show, setShow] = useState(false); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false); const [fingerprintMessage, setFingerprintMessage] = useState('');
  useEffect(() => { if (unlocked) setLocation('/vault'); }, [setLocation, unlocked]);
  useEffect(() => { const form = document.querySelector<HTMLFormElement>('main form'); if (form && !form.querySelector('[name="username"]')) { const username = document.createElement('input'); username.type = 'text'; username.name = 'username'; username.autocomplete = 'username'; username.tabIndex = -1; username.setAttribute('aria-hidden', 'true'); username.className = 'sr-only'; form.prepend(username); } }, []);
  const submit = async (event: FormEvent) => { event.preventDefault(); setMessage(''); setBusy(true); const result = mode === 'recover' ? (passphrase !== confirm ? { ok: false, message: 'Passphrases do not match.' } : await resetWithRecovery(recovery, passphrase)) : await unlock(passphrase, mode === 'create'); setBusy(false); if (!result.ok) setMessage(result.message || 'Could not continue.'); else if (mode === 'recover') setMessage('Vault reset. Unlocking your new local vault…'); };
  const fingerprint = async () => { setFingerprintMessage(''); if (!window.PublicKeyCredential || !navigator.credentials) { setFingerprintMessage('Biometric unlock is not available in this browser. Use your local passphrase instead.'); return; } try { await navigator.credentials.create({ publicKey: { challenge: crypto.getRandomValues(new Uint8Array(32)), rp: { name: 'Lumora local vault' }, user: { id: crypto.getRandomValues(new Uint8Array(16)), name: 'local-user', displayName: 'Lumora user' }, pubKeyCredParams: [{ type: 'public-key', alg: -7 }, { type: 'public-key', alg: -257 }], authenticatorSelection: { userVerification: 'required' }, timeout: 60000 } }); setFingerprintMessage('The browser verified a biometric gesture for this session. Your passphrase remains the local vault key.'); } catch { setFingerprintMessage('Biometric verification was cancelled or unavailable. No enrollment was saved.'); } };
  return <main className="app-shell app-grid flex min-h-[100dvh] flex-col"><Meta app /><header className="flex items-center justify-between px-5 py-5 sm:px-10"><Link href="/" className="focus-ring rounded-full" data-testid="link-login-brand"><BrandMark /></Link><div className="flex items-center gap-3"><span className="eyebrow hidden text-[hsl(var(--muted-foreground))] sm:block">local-first / zero knowledge</span><ThemeToggle /></div></header><div className="flex flex-1 items-center justify-center px-5 py-12 sm:px-6"><div className="grid w-full max-w-5xl items-center gap-12 lg:grid-cols-[.85fr_1.15fr]"><div className="hidden lg:block"><p className="eyebrow text-[#4b8b69]">A quiet place for your keys</p><h1 className="display mt-6 max-w-[8ch] text-[clamp(4rem,7vw,7rem)] leading-[.8] text-[#084734] dark:text-[#cef17b]">Security, <em className="text-[#4b8b69]">invisible.</em></h1><p className="mt-7 max-w-sm text-sm leading-6 text-[hsl(var(--muted-foreground))]">Nothing leaves this browser. Lumora encrypts your vault locally with Web Crypto; there is no account server waiting behind this screen.</p><div className="mt-10 flex items-center gap-3 text-xs text-[hsl(var(--muted-foreground))]"><LockKeyhole size={16} className="text-[#4b8b69]" />AES-GCM encryption · your passphrase never leaves this device</div></div><div className="soft-card mx-auto w-full max-w-[30rem] rounded-[2rem] p-6 sm:p-9"><div className="mb-8 flex items-center gap-2 border-b border-current/10 pb-5"><KeyRound className="text-[#4b8b69]" size={20} /><span className="text-sm font-semibold">{mode === 'recover' ? 'Recover your vault' : mode === 'create' ? 'Create a local vault' : 'Unlock your vault'}</span></div><div className="mb-6 flex gap-1 rounded-xl bg-[#cdefb3]/45 p-1 dark:bg-[#084734]"><button type="button" onClick={() => { setMode('unlock'); setMessage(''); }} className={`flex-1 rounded-lg px-3 py-2 text-xs font-semibold ${mode === 'unlock' ? 'bg-[#084734] text-[#cef17b]' : 'text-[hsl(var(--muted-foreground))]'}`} data-testid="button-mode-unlock">Unlock</button><button type="button" onClick={() => { setMode('create'); setMessage(''); }} className={`flex-1 rounded-lg px-3 py-2 text-xs font-semibold ${mode === 'create' ? 'bg-[#084734] text-[#cef17b]' : 'text-[hsl(var(--muted-foreground))]'}`} data-testid="button-mode-create">New vault</button><button type="button" onClick={() => { setMode('recover'); setMessage(''); }} className={`flex-1 rounded-lg px-3 py-2 text-xs font-semibold ${mode === 'recover' ? 'bg-[#084734] text-[#cef17b]' : 'text-[hsl(var(--muted-foreground))]'}`} data-testid="button-mode-recover">Recovery</button></div><form onSubmit={submit} className="space-y-4"><label className="block text-xs font-semibold">Passphrase<div className="relative mt-2"><input className="focus-ring h-12 w-full rounded-xl border border-current/15 bg-transparent px-4 pr-11 text-sm outline-none" type={show ? 'text' : 'password'} value={passphrase} onChange={(event) => setPassphrase(event.target.value)} placeholder={mode === 'create' ? 'Make it memorable, not common' : 'Your local passphrase'} autoComplete={mode === 'create' ? 'new-password' : 'current-password'} data-testid="input-passphrase" /><button type="button" onClick={() => setShow(!show)} className="focus-ring absolute right-3 top-1/2 -translate-y-1/2 text-[hsl(var(--muted-foreground))]" aria-label={show ? 'Hide passphrase' : 'Show passphrase'} data-testid="button-toggle-passphrase">{show ? <EyeOff size={16} /> : <Eye size={16} />}</button></div></label>{mode === 'recover' && <label className="block text-xs font-semibold">Recovery key<input className="focus-ring mt-2 h-12 w-full rounded-xl border border-current/15 bg-transparent px-4 font-mono text-sm outline-none" value={recovery} onChange={(event) => setRecovery(event.target.value)} placeholder="word-word-7chars-word" data-testid="input-recovery-key" /></label>}{mode === 'recover' && <label className="block text-xs font-semibold">Confirm new passphrase<input className="focus-ring mt-2 h-12 w-full rounded-xl border border-current/15 bg-transparent px-4 text-sm outline-none" type="password" value={confirm} onChange={(event) => setConfirm(event.target.value)} data-testid="input-confirm-passphrase" /></label>}<button disabled={busy} type="submit" className="magnetic-cta flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-[#084734] text-sm font-semibold text-[#cef17b] disabled:opacity-50" data-testid="button-submit-login">{busy ? 'Working locally…' : mode === 'create' ? 'Create encrypted vault' : mode === 'recover' ? 'Reset with recovery key' : 'Unlock Lumora'}<ArrowRight size={15} /></button></form>{mode === 'create' && <p className="mt-4 text-xs leading-5 text-[hsl(var(--muted-foreground))]">A recovery key will be generated after setup. Save it somewhere offline; it is the only reset path.</p>}{mode === 'unlock' && <button type="button" onClick={fingerprint} className="focus-ring mt-4 flex h-11 w-full items-center justify-center gap-2 rounded-xl border border-current/15 text-xs font-semibold transition hover:bg-current/5" data-testid="button-fingerprint-login"><Fingerprint size={17} className="text-[#4b8b69]" />Try fingerprint / device biometrics</button>}{fingerprintMessage && <p className="mt-3 rounded-xl bg-[#cdefb3]/50 p-3 text-xs leading-5 text-[#084734] dark:bg-[#084734] dark:text-[#cdefb3]" data-testid="status-fingerprint">{fingerprintMessage}</p>}{message && <p className={`mt-4 rounded-xl p-3 text-xs leading-5 ${message.startsWith('Vault reset') ? 'bg-[#cdefb3] text-[#084734]' : 'bg-[#084734]/10 text-[hsl(var(--foreground))]'}`} role="status" data-testid="status-login">{message}</p>}{mode === 'recover' && !recoveryKey && <p className="mt-4 text-xs text-[hsl(var(--muted-foreground))]">No recovery key exists in this browser yet. Create a vault first.</p>}</div></div></div></main>;
}

function Sidebar({ mobileOpen, close }: { mobileOpen: boolean; close: () => void }) {
  const { activeView, setActiveView, lock, records } = useVault(); const [, setLocation] = useLocation();
  const items: { key: ActiveView; label: string; icon: typeof LayoutGrid; count?: number }[] = [{ key: 'all', label: 'All logins', icon: LayoutGrid, count: records.filter((r) => !r.deleted).length }, { key: 'favorites', label: 'Starred', icon: Star, count: records.filter((r) => r.favorite && !r.deleted).length }, { key: 'trash', label: 'Trash', icon: Trash2, count: records.filter((r) => r.deleted).length }, { key: 'activity', label: 'Activity', icon: Clock3 }];
  return <><aside className={`${mobileOpen ? 'translate-x-0' : '-translate-x-full'} fixed inset-y-0 left-0 z-40 flex w-[17rem] flex-col border-r border-current/10 bg-[hsl(var(--background))] p-5 transition-transform lg:static lg:translate-x-0`}><div className="flex items-center justify-between"><Link href="/vault" className="focus-ring rounded-full" onClick={close} data-testid="link-vault-brand"><BrandMark /></Link><button type="button" onClick={close} className="focus-ring rounded-lg p-2 lg:hidden" aria-label="Close navigation" data-testid="button-close-sidebar"><X size={18} /></button></div><div className="mt-12 flex-1"><p className="eyebrow mb-3 text-[hsl(var(--muted-foreground))]">Your space</p><nav className="space-y-1" aria-label="Vault navigation">{items.map(({ key, label, icon: Icon, count }) => <button type="button" key={key} onClick={() => { setActiveView(key); close(); }} className={`focus-ring flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm transition ${activeView === key ? 'bg-[#084734] font-semibold text-[#cef17b]' : 'text-[hsl(var(--muted-foreground))] hover:bg-current/5 hover:text-[hsl(var(--foreground))]'}`} data-testid={`button-view-${key}`}><Icon size={17} strokeWidth={1.7} /><span className="flex-1">{label}</span>{count !== undefined && <span className="font-mono text-[0.68rem] opacity-70">{count}</span>}</button>)}</nav><div className="mt-10 border-t border-current/10 pt-5"><button type="button" onClick={() => { setActiveView('settings'); close(); }} className={`focus-ring flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm ${activeView === 'settings' ? 'bg-[#084734] text-[#cef17b]' : 'text-[hsl(var(--muted-foreground))] hover:bg-current/5'}`} data-testid="button-view-settings"><Settings size={17} /><span>Settings</span></button></div></div><div className="rounded-2xl bg-[#cdefb3]/55 p-4 text-[#084734] dark:bg-[#084734] dark:text-[#cdefb3]"><div className="flex items-center gap-2 text-xs font-semibold"><ShieldCheck size={15} /> Protected locally</div><p className="mt-2 text-[0.68rem] leading-5 opacity-75">Your encrypted vault never leaves this browser.</p></div><button type="button" onClick={() => { lock(); setLocation('/login'); }} className="focus-ring mt-4 flex items-center gap-3 rounded-xl px-3 py-3 text-left text-sm text-[hsl(var(--muted-foreground))] hover:bg-current/5" data-testid="button-lock-vault"><LogOut size={17} />Lock vault</button></aside>{mobileOpen && <button type="button" onClick={close} className="fixed inset-0 z-30 bg-[#084734]/25 lg:hidden" aria-label="Close navigation overlay" data-testid="button-sidebar-overlay" />}</>;
}

function Generator({ onUse }: { onUse: (password: string) => void }) {
  const [password, setPassword] = useState(randomPassword()); const [copied, setCopied] = useState(false);
  const copy = async () => { await navigator.clipboard?.writeText(password); setCopied(true); window.setTimeout(() => setCopied(false), 1500); };
  return <section className="soft-card rounded-2xl p-5" data-testid="panel-password-generator"><div className="flex items-start justify-between"><div><p className="eyebrow text-[#4b8b69]">Password generator</p><h3 className="mt-2 text-lg font-semibold">A better default.</h3></div><Zap size={18} className="text-[#4b8b69]" /></div><div className="mt-5 flex items-center gap-2 rounded-xl bg-[#084734] p-2 text-[#cef17b]"><input readOnly value={password} className="min-w-0 flex-1 bg-transparent px-2 font-mono text-xs tracking-wider outline-none" aria-label="Generated password" data-testid="input-generated-password" /><button type="button" onClick={copy} className="focus-ring rounded-lg p-2 hover:bg-[#cdefb3]/20" aria-label="Copy generated password" data-testid="button-copy-generated-password">{copied ? <Check size={15} /> : <Copy size={15} />}</button><button type="button" onClick={() => { setPassword(randomPassword()); setCopied(false); }} className="focus-ring rounded-lg p-2 hover:bg-[#cdefb3]/20" aria-label="Generate another password" data-testid="button-regenerate-password"><RefreshCw size={15} /></button></div><div className="mt-4 flex gap-1"><span className="h-1.5 flex-1 rounded-full bg-[#084734]" /><span className="h-1.5 flex-1 rounded-full bg-[#084734]" /><span className="h-1.5 flex-1 rounded-full bg-[#084734]" /><span className="h-1.5 flex-1 rounded-full bg-[#cef17b]" /></div><button type="button" onClick={() => onUse(password)} className="focus-ring mt-4 flex items-center gap-2 text-xs font-semibold text-[#4b8b69]" data-testid="button-use-generated-password">Use in a new login <ArrowRight size={13} /></button></section>;
}

function RecordDialog({ record, close, initialPassword }: { record?: LoginRecord; close: () => void; initialPassword?: string }) {
  const { saveRecord } = useVault(); const [form, setForm] = useState({ name: record?.name ?? '', username: record?.username ?? '', password: record?.password ?? initialPassword ?? randomPassword(), url: record?.url ?? '', category: record?.category ?? 'Personal' }); const [visible, setVisible] = useState(false); const [saved, setSaved] = useState(false);
  const update = (key: keyof typeof form, value: string) => setForm((current) => ({ ...current, [key]: value }));
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!form.name.trim() || !form.password.trim()) return; await saveRecord(form, record?.id); setSaved(true); window.setTimeout(close, 500); };
  return <div className="fixed inset-0 z-50 flex items-end justify-center bg-[#084734]/35 p-0 sm:items-center sm:p-6"><div className="soft-card max-h-[92dvh] w-full max-w-xl overflow-y-auto rounded-t-[2rem] p-6 sm:rounded-[2rem] sm:p-8" role="dialog" aria-modal="true" aria-labelledby="record-dialog-title" data-testid="dialog-record"><div className="flex items-start justify-between"><div><p className="eyebrow text-[#4b8b69]">{record ? 'Edit login' : 'New login'}</p><h2 id="record-dialog-title" className="mt-2 text-2xl font-semibold">{record ? 'Keep it current.' : 'Put a door in order.'}</h2></div><button type="button" onClick={close} className="focus-ring rounded-full p-2 hover:bg-current/5" aria-label="Close login dialog" data-testid="button-close-record-dialog"><X size={18} /></button></div><form onSubmit={submit} className="mt-7 space-y-4"><div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-semibold">Name<input required value={form.name} onChange={(e) => update('name', e.target.value)} className="focus-ring mt-2 h-11 w-full rounded-xl border border-current/15 bg-transparent px-3 text-sm outline-none" placeholder="e.g. Northstar Bank" data-testid="input-record-name" /></label><label className="text-xs font-semibold">Category<select value={form.category} onChange={(e) => update('category', e.target.value)} className="focus-ring mt-2 h-11 w-full rounded-xl border border-current/15 bg-[hsl(var(--background))] px-3 text-sm outline-none" data-testid="select-record-category"><option>Personal</option><option>Finance</option><option>Work</option><option>Home</option><option>Health</option><option>Shopping</option></select></label></div><label className="block text-xs font-semibold">Website<input value={form.url} onChange={(e) => update('url', e.target.value)} className="focus-ring mt-2 h-11 w-full rounded-xl border border-current/15 bg-transparent px-3 text-sm outline-none" placeholder="https://example.com" data-testid="input-record-url" /></label><label className="block text-xs font-semibold">Username<input value={form.username} onChange={(e) => update('username', e.target.value)} className="focus-ring mt-2 h-11 w-full rounded-xl border border-current/15 bg-transparent px-3 text-sm outline-none" placeholder="you@example.com" data-testid="input-record-username" /></label><label className="block text-xs font-semibold">Password<div className="relative mt-2"><input required type={visible ? 'text' : 'password'} value={form.password} onChange={(e) => update('password', e.target.value)} className="focus-ring h-11 w-full rounded-xl border border-current/15 bg-transparent px-3 pr-10 font-mono text-sm outline-none" data-testid="input-record-password" /><button type="button" onClick={() => setVisible(!visible)} className="focus-ring absolute right-2 top-1/2 -translate-y-1/2 p-2" aria-label={visible ? 'Hide record password' : 'Show record password'} data-testid="button-toggle-record-password">{visible ? <EyeOff size={15} /> : <Eye size={15} />}</button></div></label><div className="flex justify-end gap-3 border-t border-current/10 pt-5"><button type="button" onClick={close} className="focus-ring rounded-xl px-4 py-3 text-sm font-semibold text-[hsl(var(--muted-foreground))]" data-testid="button-cancel-record">Cancel</button><button type="submit" className="focus-ring rounded-xl bg-[#084734] px-5 py-3 text-sm font-semibold text-[#cef17b]" data-testid="button-save-record">{saved ? <Check size={16} /> : record ? 'Save changes' : 'Save login'}</button></div></form></div></div>;
}

function Vault() {
  const { unlocked, records, activity, activeView, setActiveView, toggleFavorite, trashRecord, restoreRecord, recoveryKey, theme } = useVault(); const [, setLocation] = useLocation(); const [query, setQuery] = useState(''); const [category, setCategory] = useState('all'); const [status, setStatus] = useState('active'); const [selected, setSelected] = useState<LoginRecord>(); const [draftPassword, setDraftPassword] = useState<string>(); const [dialog, setDialog] = useState(false); const [mobileOpen, setMobileOpen] = useState(false); const [toast, setToast] = useState(''); const [installEvent, setInstallEvent] = useState<BeforeInstallPromptEvent | null>(null);
  useEffect(() => { if (!unlocked) setLocation('/login'); }, [setLocation, unlocked]);
  useEffect(() => { const handler = (event: Event) => { event.preventDefault(); setInstallEvent(event as BeforeInstallPromptEvent); }; window.addEventListener('beforeinstallprompt', handler); return () => window.removeEventListener('beforeinstallprompt', handler); }, []);
  const activeRecords = useMemo(() => records.filter((record) => activeView === 'trash' ? record.deleted : !record.deleted).filter((record) => activeView !== 'favorites' || record.favorite).filter((record) => category === 'all' || record.category === category).filter((record) => activeView === 'trash' || status === 'all' || (status === 'active' ? !record.deleted : record.deleted)).filter((record) => [record.name, record.username, record.url, record.category].join(' ').toLowerCase().includes(query.toLowerCase())), [activeView, category, query, records, status]);
  const categories = [...new Set(records.map((record) => record.category))]; const notify = (value: string) => { setToast(value); window.setTimeout(() => setToast(''), 2200); };
  const copyPassword = async (record: LoginRecord) => { await navigator.clipboard?.writeText(record.password); notify(`${record.name} password copied`); };
  const install = async () => { if (!installEvent) { notify('Install is not available yet. Use your browser menu to add Lumora to your home screen.'); return; } await installEvent.prompt(); setInstallEvent(null); };
  if (!unlocked) return null;
  if (activeView === 'activity') return <VaultLayout mobileOpen={mobileOpen} setMobileOpen={setMobileOpen}><PageHeader title="Activity" eyebrow="A clear trail" onAdd={() => setActiveView('all')} /><div className="soft-card rounded-2xl p-5 sm:p-7"><div className="space-y-1">{activity.length === 0 ? <EmptyState icon={Clock3} title="Nothing here yet" copy="When you create, update, favorite, or restore a login, it will appear here." /> : activity.map((event) => <div key={event.id} className="flex items-center gap-4 border-b border-current/8 py-4 last:border-0" data-testid={`row-activity-${event.id}`}><span className="flex h-9 w-9 items-center justify-center rounded-full bg-[#cdefb3] text-[#084734]"><ActivityIcon action={event.action} /></span><div className="flex-1"><p className="text-sm font-medium"><span className="capitalize">{event.action}</span> <span className="text-[hsl(var(--muted-foreground))]">{event.recordName}</span></p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{formatDate(event.timestamp)}</p></div></div>)}</div></div>{toast && <Toast text={toast} />}</VaultLayout>;
  if (activeView === 'settings') return <VaultLayout mobileOpen={mobileOpen} setMobileOpen={setMobileOpen}><PageHeader title="Settings" eyebrow="Your preferences" onAdd={() => setActiveView('all')} /><SettingsPanel recoveryKey={recoveryKey} install={install} installReady={!!installEvent} theme={theme} /></VaultLayout>;
  return <VaultLayout mobileOpen={mobileOpen} setMobileOpen={setMobileOpen}><PageHeader title={activeView === 'trash' ? 'Trash' : activeView === 'favorites' ? 'Starred logins' : 'All logins'} eyebrow={activeView === 'trash' ? 'Soft deleted, not gone' : 'Your private index'} onAdd={() => { setSelected(undefined); setDraftPassword(undefined); setDialog(true); }} /><div className="grid gap-6 xl:grid-cols-[1fr_19rem]"><section><div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[hsl(var(--muted-foreground))]" size={16} /><input value={query} onChange={(e) => setQuery(e.target.value)} type="search" placeholder="Search name, domain, category…" className="focus-ring h-12 w-full rounded-xl border border-current/12 bg-[hsl(var(--card))] pl-10 pr-4 text-sm outline-none" aria-label="Search logins" data-testid="input-search-logins" /></div><select value={category} onChange={(e) => setCategory(e.target.value)} className="focus-ring h-12 rounded-xl border border-current/12 bg-[hsl(var(--card))] px-3 text-sm outline-none" aria-label="Filter by category" data-testid="select-filter-category"><option value="all">Every category</option>{categories.map((value) => <option key={value}>{value}</option>)}</select><select value={status} onChange={(e) => setStatus(e.target.value)} className="focus-ring h-12 rounded-xl border border-current/12 bg-[hsl(var(--card))] px-3 text-sm outline-none" aria-label="Filter by status" data-testid="select-filter-status"><option value="active">Active</option><option value="all">All status</option><option value="trash">Trash</option></select></div><div className="mb-4 flex items-center justify-between"><p className="text-xs text-[hsl(var(--muted-foreground))]">{activeRecords.length} {activeRecords.length === 1 ? 'login' : 'logins'} in view</p><button type="button" onClick={() => { setQuery(''); setCategory('all'); setStatus('active'); }} className="focus-ring text-xs font-semibold text-[#4b8b69]" data-testid="button-clear-filters">Clear filters</button></div>{activeRecords.length === 0 ? <div className="soft-card rounded-2xl"><EmptyState icon={Search} title={activeView === 'trash' ? 'Trash is clear' : 'Nothing matches'} copy={activeView === 'trash' ? 'Restored things return to your main vault.' : 'Try a different search, or add your first login.'} /></div> : <div className="space-y-2">{activeRecords.map((record) => <RecordRow key={record.id} record={record} copy={() => copyPassword(record)} edit={() => { setSelected(record); setDraftPassword(undefined); setDialog(true); }} favorite={() => toggleFavorite(record.id)} trash={() => { trashRecord(record.id); notify(`${record.name} moved to trash`); }} restore={() => { restoreRecord(record.id); notify(`${record.name} restored`); }} />)}</div>}</section><aside className="space-y-5"><Generator onUse={(password) => { setSelected(undefined); setDraftPassword(password); setDialog(true); }} /><div className="soft-card rounded-2xl p-5"><p className="eyebrow text-[#4b8b69]">At a glance</p><div className="mt-4 grid grid-cols-2 gap-3"><Stat value={records.filter((r) => !r.deleted).length} label="active" /><Stat value={records.filter((r) => r.favorite && !r.deleted).length} label="starred" /></div></div></aside></div>{dialog && <RecordDialog record={selected} initialPassword={draftPassword} close={() => setDialog(false)} />}{toast && <Toast text={toast} />}</VaultLayout>;
}

type BeforeInstallPromptEvent = Event & { prompt: () => Promise<void>; userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }> };
function VaultLayout({ children, mobileOpen, setMobileOpen }: { children: ReactNode; mobileOpen: boolean; setMobileOpen: (value: boolean) => void }) { return <main className="app-shell flex"><Sidebar mobileOpen={mobileOpen} close={() => setMobileOpen(false)} /><div className="min-w-0 flex-1"><div className="flex items-center justify-between border-b border-current/10 px-5 py-4 lg:hidden"><button type="button" onClick={() => setMobileOpen(true)} className="focus-ring rounded-lg p-2" aria-label="Open navigation" data-testid="button-open-sidebar"><Menu size={20} /></button><BrandMark /><div className="w-9" /></div><div className="mx-auto max-w-[1280px] px-5 py-7 sm:px-8 sm:py-10 lg:px-12">{children}</div></div></main>; }
function PageHeader({ title, eyebrow, onAdd }: { title: string; eyebrow: string; onAdd: () => void }) { const { theme } = useVault(); return <header className="mb-8 flex items-end justify-between gap-4"><div><p className="eyebrow text-[#4b8b69]">{eyebrow}</p><h1 className="display mt-3 text-[clamp(2.8rem,5vw,5rem)] leading-[.84] text-[#084734] dark:text-[#cef17b]">{title}</h1></div><div className="flex items-center gap-2"><ThemeToggle /><button type="button" onClick={onAdd} className="focus-ring flex items-center gap-2 rounded-xl bg-[#084734] px-4 py-3 text-sm font-semibold text-[#cef17b]" data-testid="button-add-login"><Plus size={16} /> <span className="hidden sm:inline">New login</span></button></div></header>; }
function RecordRow({ record, copy, edit, favorite, trash, restore }: { record: LoginRecord; copy: () => void; edit: () => void; favorite: () => void; trash: () => void; restore: () => void }) { const [revealed, setRevealed] = useState(false); return <article className="soft-card lift group rounded-2xl p-4 sm:p-5" data-testid={`row-login-${record.id}`}><div className="flex items-center gap-3 sm:gap-4"><span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-[#cdefb3] text-lg font-semibold text-[#084734]">{record.name[0]?.toUpperCase()}</span><button type="button" onClick={edit} className="focus-ring min-w-0 flex-1 text-left" data-testid={`button-edit-login-${record.id}`}><span className="block truncate text-sm font-semibold">{record.name}</span><span className="mt-1 block truncate text-xs text-[hsl(var(--muted-foreground))]">{record.username || hostname(record.url)} · {record.category}</span></button><button type="button" onClick={favorite} className={`focus-ring rounded-lg p-2 ${record.favorite ? 'text-[#084734] dark:text-[#cef17b]' : 'text-[hsl(var(--muted-foreground))]'}`} aria-label={record.favorite ? `Unstar ${record.name}` : `Star ${record.name}`} data-testid={`button-favorite-login-${record.id}`}><Star size={17} fill={record.favorite ? 'currentColor' : 'none'} /></button><button type="button" onClick={() => setRevealed(!revealed)} className="focus-ring hidden rounded-lg p-2 text-[hsl(var(--muted-foreground))] hover:bg-current/5 sm:block" aria-label={revealed ? 'Hide password' : 'Show password'} data-testid={`button-reveal-login-${record.id}`}>{revealed ? <EyeOff size={16} /> : <Eye size={16} />}</button><button type="button" onClick={copy} className="focus-ring rounded-lg p-2 text-[hsl(var(--muted-foreground))] hover:bg-current/5" aria-label={`Copy ${record.name} password`} data-testid={`button-copy-login-${record.id}`}><Copy size={16} /></button>{record.deleted ? <button type="button" onClick={restore} className="focus-ring rounded-lg p-2 text-[#4b8b69] hover:bg-current/5" aria-label={`Restore ${record.name}`} data-testid={`button-restore-login-${record.id}`}><Undo2 size={16} /></button> : <button type="button" onClick={trash} className="focus-ring rounded-lg p-2 text-[hsl(var(--muted-foreground))] hover:text-red-700" aria-label={`Move ${record.name} to trash`} data-testid={`button-trash-login-${record.id}`}><Trash2 size={16} /></button>}</div>{revealed && <div className="mt-4 flex items-center gap-2 rounded-xl bg-[#084734] px-3 py-2 text-[#cef17b]"><span className="flex-1 overflow-hidden text-ellipsis font-mono text-xs">{record.password}</span><button type="button" onClick={copy} className="focus-ring rounded p-1" aria-label="Copy revealed password" data-testid={`button-copy-revealed-${record.id}`}><Clipboard size={14} /></button></div>}</article>; }
function ActivityIcon({ action }: { action: string }) { if (action === 'deleted') return <Trash2 size={15} />; if (action === 'restored') return <Undo2 size={15} />; if (action.includes('favor')) return <Star size={15} />; return action === 'created' ? <Plus size={15} /> : <RefreshCw size={15} />; }
function EmptyState({ icon: Icon, title, copy }: { icon: typeof Search; title: string; copy: string }) { return <div className="flex flex-col items-center justify-center px-6 py-20 text-center"><span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-[#cdefb3] text-[#084734]"><Icon size={20} /></span><h2 className="mt-5 text-lg font-semibold">{title}</h2><p className="mt-2 max-w-xs text-sm leading-6 text-[hsl(var(--muted-foreground))]">{copy}</p></div>; }
function Stat({ value, label }: { value: number; label: string }) { return <div className="rounded-xl bg-[#cdefb3]/55 p-3 text-[#084734] dark:bg-[#084734] dark:text-[#cdefb3]"><p className="text-2xl font-semibold">{value}</p><p className="mt-1 text-[0.68rem] uppercase tracking-wider opacity-70">{label}</p></div>; }
function Toast({ text }: { text: string }) { return <div className="toast-in fixed bottom-5 right-5 z-[60] flex items-center gap-2 rounded-xl bg-[#084734] px-4 py-3 text-xs font-semibold text-[#cef17b] shadow-xl" role="status" data-testid="status-toast"><Check size={15} />{text}</div>; }
function SettingsPanel({ recoveryKey, install, installReady, theme }: { recoveryKey: string | null; install: () => void; installReady: boolean; theme: Theme }) { const [revealed, setRevealed] = useState(false); const [copied, setCopied] = useState(false); const copy = async () => { if (recoveryKey) await navigator.clipboard?.writeText(recoveryKey); setCopied(true); window.setTimeout(() => setCopied(false), 1600); }; return <div className="grid gap-5 lg:grid-cols-2"><section className="soft-card rounded-2xl p-6"><div className="flex items-center gap-3"><KeyRound className="text-[#4b8b69]" size={20} /><div><h2 className="font-semibold">Recovery key</h2><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Offline reset path for this browser.</p></div></div>{recoveryKey ? <><div className="mt-6 rounded-xl bg-[#084734] p-4 font-mono text-sm tracking-wider text-[#cef17b]">{revealed ? recoveryKey : '•••• •••• ••••••• ••••'}</div><div className="mt-4 flex gap-2"><button type="button" onClick={() => setRevealed(!revealed)} className="focus-ring rounded-xl border border-current/15 px-3 py-2 text-xs font-semibold" data-testid="button-toggle-recovery">{revealed ? 'Hide key' : 'Reveal key'}</button><button type="button" onClick={copy} className="focus-ring flex items-center gap-2 rounded-xl border border-current/15 px-3 py-2 text-xs font-semibold" data-testid="button-copy-recovery"><Copy size={14} />{copied ? 'Copied' : 'Copy key'}</button></div><p className="mt-4 text-xs leading-5 text-[hsl(var(--muted-foreground))]">Lumora cannot retrieve this key. Store it in a safe offline place; it is not sent anywhere.</p></> : <p className="mt-6 rounded-xl bg-current/5 p-4 text-xs text-[hsl(var(--muted-foreground))]">Create a vault to generate a recovery key.</p>}</section><section className="soft-card rounded-2xl p-6"><div className="flex items-center gap-3"><Download className="text-[#4b8b69]" size={20} /><div><h2 className="font-semibold">Install Lumora</h2><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Keep your vault one tap away.</p></div></div><button type="button" onClick={install} className="focus-ring mt-6 flex w-full items-center justify-center gap-2 rounded-xl bg-[#084734] px-4 py-3 text-sm font-semibold text-[#cef17b]" data-testid="button-install-app"><Download size={16} />{installReady ? 'Install Lumora' : 'Show install options'}</button><p className="mt-4 text-xs leading-5 text-[hsl(var(--muted-foreground))]" data-testid="text-install-help">{installReady ? 'Your browser has an install prompt ready.' : 'If no prompt appears, use your browser menu and choose “Add to Home Screen” or “Install”.'}</p><div className="mt-8 border-t border-current/10 pt-5"><p className="eyebrow text-[#4b8b69]">Current theme</p><p className="mt-2 text-sm">{theme === 'dark' ? 'Night green' : 'Daylight green'} — toggle from any header.</p></div></section></div>; }

function Router() { const [location] = useLocation(); return <ErrorBoundary resetKey={location}><Switch><Route path="/" component={Home} /><Route path="/login" component={Login} /><Route path="/vault" component={Vault} /><Route component={NotFound} /></Switch></ErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><VaultProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter></VaultProvider><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;